SourceCode.Declaration:
/// <summary>
/// Extension of BOMVersion table
/// </summary>
[ExtensionOf(tableStr(BOMVersion))]
public final class NDXBomVersion_tbl_Extension
{
}

Method.Source:
/// <summary>
/// Finds valid bom version record
/// </summary>
/// <param name = "_itemId">itemid</param>
/// <param name = "_forUpdate">true or false</param>
/// <returns>BOMVersion record</returns>
static public BOMVersion findValidActive(ItemId _itemId, boolean _forUpdate  = false)
{
    BOMVersion  bomVersion;

    if (!_itemId)
    {
        return bomVersion;
    }

    bomVersion.selectForUpdate(_forUpdate);

    select  bomVersion
        where   bomVersion.ItemId == _itemId
            &&  bomVersion.Active
            &&  bomVersion.FromQty == 0
        &&  (bomVersion.ToDate >= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())
                 || (bomVersion.FromDate != DateNull() && bomVersion.ToDate == DateNull() && bomVersion.FromDate <= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))
                 || (bomVersion.FromDate == DateNull() && bomVersion.ToDate == DateNull()));

    return bomVersion;
}
